$ErrorActionPreference = "Stop"

if (-not (Test-Path ".git")) {
  Write-Host "ERROR: run this from your local canary repo root (the folder with .git)." -ForegroundColor Red
  exit 1
}

Write-Host "Updating Canary README + live board..." -ForegroundColor Cyan
New-Item -ItemType Directory -Force -Path "assets" | Out-Null
New-Item -ItemType Directory -Force -Path "docs" | Out-Null

$readmeB64 = ""
$boardB64 = ""
$boardDocB64 = ""

[IO.File]::WriteAllBytes((Join-Path (Get-Location) "README.md"), [Convert]::FromBase64String($readmeB64))
[IO.File]::WriteAllBytes((Join-Path (Get-Location) "assets\board-live.png"), [Convert]::FromBase64String($boardB64))
[IO.File]::WriteAllBytes((Join-Path (Get-Location) "docs\BOARD.md"), [Convert]::FromBase64String($boardDocB64))

git add README.md assets/board-live.png docs/BOARD.md
$diff = git diff --cached --name-only
if (-not $diff) {
  Write-Host "Nothing changed. README upgrade is already applied." -ForegroundColor Yellow
  exit 0
}

Write-Host "Files staged:" -ForegroundColor Green
$diff | ForEach-Object { Write-Host "  $_" }

git commit -m "refresh README with live board"
if ($LASTEXITCODE -ne 0) { throw "git commit failed" }

git push
if ($LASTEXITCODE -ne 0) { throw "git push failed" }

Write-Host "DONE. GitHub README updated." -ForegroundColor Green
